"""Replay every complete-byte likelihood and generated byte, at the recorded runtime."""
import argparse
import json
import os
from pathlib import Path
import sys
import time
os.environ.setdefault('CUBLAS_WORKSPACE_CONFIG',':4096:8')
import numpy as np
import torch
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from model.qasc_generation_data import load
from model.qasc_context import POLICIES,check
from model.qasc_surface import conditions,plan,evaluate,render
from model.surface_renderer import Renderer
from model.strict_surface import encode_complete,losses_encoded
from model.renderer_conditioning import gpu_lease
from model.scifact_readout import array_sha
from audit.qasc_region_readback import read as read_region,read_json
from audit.qasc_surface_readback import read,records
from text.evaluation_multiscale import file_sha
from senses.trajectory_population import publish
from lens.lenscommon import run_cli

def main():
    p=argparse.ArgumentParser(description=__doc__)
    for n in ('population','native','targets','target-native','raw','proof','region-model','model','output'):p.add_argument('--'+n,type=Path,required=True)
    a=p.parse_args();check(not a.output.exists(),'SURFACE_REPLAY_EXISTS');started=time.perf_counter();phases={};torch.set_num_threads(32)
    ctx=load(a.population,a.native,a.targets,a.target_native,a.raw,a.proof);read_region(a.region_model,ctx);cold=read(a.model,ctx,a.region_model)
    runtime=read_json(a.model/'runtime.json');check(runtime['torch']==torch.__version__ and runtime['cuda']==torch.version.cuda and runtime['platform']==sys.platform,'SURFACE_REPLAY_RUNTIME')
    for name,pin in runtime['source_code'].items():check(file_sha(Path(__file__).parents[1]/'model'/name)==pin,'SURFACE_REPLAY_CODE')
    a.output.mkdir(parents=True);publish(a.output/'cold.json',cold);phases['input_output_and_runtime_cold_read']=time.perf_counter()-started;tick=time.perf_counter()
    resident=gpu_lease(None,'qasc-complete-byte-renderer-full-replay');(a.output/'gpu-before.txt').write_text(resident,encoding='utf-8')
    check(torch.cuda.get_device_name(0)==runtime['device'],'SURFACE_REPLAY_DEVICE')
    texts=[ctx['texts'][i] for i in ctx['target_index']];packed=encode_complete(texts,'cuda',512);lengths=np.array([len(t.encode())+2 for t in texts])
    phases['lease_and_complete_bytes']=time.perf_counter()-tick;results={}
    for policy in POLICIES:
        tick=time.perf_counter();folder=a.model/policy;rr=ctx['policies'][policy];values=conditions(ctx,a.region_model/policy)
        hashes={name:[array_sha(v.cpu().numpy()) for v in arrays] for name,arrays in values.items()}
        check(hashes==read_json(folder/'conditioning.json')['hashes'],'SURFACE_REPLAY_CONDITIONS')
        order,heldout,selected=plan(rr);donors=np.load(folder/'donors.npy',allow_pickle=False)
        phases[policy+'/conditions']=time.perf_counter()-tick
        for arm in ('true','gaussian','predicted'):
            tick=time.perf_counter();root=folder/arm;model=Renderer([768]*6,256,4,8).cuda().train()
            model.load_state_dict(torch.load(folder/'initial.pt',map_location='cpu',weights_only=True));ix=order[0];length=int(lengths[ix].max())
            with torch.autocast('cuda',dtype=torch.bfloat16):loss,bb,eb,counts=losses_encoded(model,[x[ix] for x in values[arm]],packed[0][ix,:length],packed[1][ix,:length])
            with np.load(root/'objective.npz',allow_pickle=False) as z:
                check(float(loss.detach())==read_json(root/'objective.json')['loss'] and np.array_equal(bb.detach().cpu().numpy(),z['byte_nll_bits'])
                      and np.array_equal(eb.detach().cpu().numpy(),z['eos_nll_bits']) and np.array_equal(counts.cpu().numpy(),z['bytes']),'SURFACE_REPLAY_OBJECTIVE')
            model.load_state_dict(torch.load(root/'renderer.pt',map_location='cpu',weights_only=True));model.requires_grad_(False).eval()
            scores=evaluate(model,values,packed,lengths,heldout,rr,donors);check(scores==records(root/'scores.jsonl'),'SURFACE_REPLAY_SCORES')
            generated=render(model,values,selected,rr,texts,arm,policy);check(generated==records(root/'renders.jsonl'),'SURFACE_REPLAY_BYTES')
            results[policy+'/'+arm]=dict(checkpoint_sha256=file_sha(root/'renderer.pt'),initial_objective_bitwise_equal=True,
                    all_likelihood_rows_equal=True,likelihood_rows=len(scores),all_render_tokens_text_status_equal=True,renders=len(generated))
            del model;torch.cuda.empty_cache();phases[policy+'/'+arm]=time.perf_counter()-tick
            print(json.dumps(dict(replayed=policy+'/'+arm,seconds=phases[policy+'/'+arm])),flush=True)
        del values;torch.cuda.empty_cache()
    tick=time.perf_counter();before=read_json(a.model/'before.json');check(all(file_sha(Path(p))==pin for p,pin in before.items()),'SURFACE_REPLAY_PARENTS')
    check(file_sha(a.model/'report.json')==cold['report_sha256'],'SURFACE_REPLAY_RESULT');phases['final_hashes']=time.perf_counter()-tick;wall=time.perf_counter()-started
    publish(a.output/'report.json',dict(model_report_sha256=cold['report_sha256'],fits=results,all_cases_and_bytes_replayed=True,
            originals_unchanged=True,acceptance='author-checked',scientific_admission=False,served=False,
            phases_seconds=phases,wall_seconds=wall,phase_coverage=sum(phases.values())/wall,code_sha256=file_sha(Path(__file__))))
    print(json.dumps(dict(fits=len(results),report_sha256=file_sha(a.output/'report.json'),wall_seconds=wall)),flush=True)

if __name__=='__main__':sys.exit(run_cli(main))
